import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import Cursor from "./Cursor";
import {
  FaInstagram,
  FaYoutube,
  FaFacebookF,
  FaTwitter,
  FaTiktok,
  FaBars,
  FaTimes
} from "react-icons/fa";

export default function LandingPage() {
  const socials = [
    { icon: FaInstagram, link: "https://instagram.com" },
    { icon: FaYoutube, link: "https://youtube.com" },
    { icon: FaFacebookF, link: "https://facebook.com" },
    { icon: FaTwitter, link: "https://x.com" },
    { icon: FaTiktok, link: "https://tiktok.com" },
  ];

  const eventDate = new Date("2026-06-30T18:00:00").getTime();

  const [timeLeft, setTimeLeft] = useState({
    days: "00",
    hours: "00",
    minutes: "00",
    seconds: "00",
  });

  function getTimeRemaining() {
    const now = new Date().getTime();
    const distance = eventDate - now;

    if (distance <= 0) {
      return {
        days: "00",
        hours: "00",
        minutes: "00",
        seconds: "00",
      };
    }

    return {
      days: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, "0"),
      hours: String(Math.floor((distance / (1000 * 60 * 60)) % 24)).padStart(2, "0"),
      minutes: String(Math.floor((distance / (1000 * 60)) % 60)).padStart(2, "0"),
      seconds: String(Math.floor((distance / 1000) % 60)).padStart(2, "0"),
    };
  }

  useEffect(() => {
    const updateTime = () => {
      setTimeLeft(getTimeRemaining());
    };

    updateTime();
    const timer = setInterval(updateTime, 1000);

    return () => clearInterval(timer);
  }, []);

  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = (id) => {
    const section = document.getElementById(id);

    if (section) {
      section.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }

    setMenuOpen(false);
  };

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuOpen && !event.target.closest('.mobile-menu') && !event.target.closest('.hamburger-btn')) {
        setMenuOpen(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [menuOpen]);

  // Prevent body scroll when menu is open
  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [menuOpen]);

  return (
    <>
      <Cursor />
      <div className="bg-black text-white font-[Inter] overflow-x-hidden">
        {/* NAVBAR */}
        <nav className="fixed w-full z-50 bg-black/95 backdrop-blur-sm border-b border-neutral-900">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 h-16 flex items-center justify-between">
            {/* Logo */}
            <div className="flex items-center flex-shrink-0">
              <img
                src="/gfc-logo.png"
                alt="GFC Logo"
                className="h-10 sm:h-12 md:h-14 lg:h-16 object-contain"
              />
            </div>

            {/* DESKTOP MENU */}
            <ul className="hidden lg:flex gap-6 xl:gap-8 text-xs uppercase tracking-wider">
              {navItems.map((item) => (
                <li
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="hover:text-red-500 cursor-pointer transition"
                >
                  {item.name}
                </li>
              ))}
            </ul>

            {/* DESKTOP TICKET BUTTON */}
            <button className="hidden lg:block bg-red-600 hover:bg-red-700 px-4 py-2 text-xs font-semibold transition">
              GET TICKETS
            </button>

            {/* MOBILE HAMBURGER BUTTON */}
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              className="lg:hidden hamburger-btn text-white text-2xl p-2 z-50"
              aria-label="Toggle menu"
            >
              {menuOpen ? <FaTimes /> : <FaBars />}
            </button>
          </div>

          {/* MOBILE MENU OVERLAY */}
          {menuOpen && (
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm lg:hidden z-40" />
          )}

          {/* MOBILE MENU */}
          <div
            className={`
              fixed top-16 right-0 h-[calc(100vh-4rem)] w-full max-w-xs
              bg-black border-l border-neutral-800
              transform transition-transform duration-300 ease-in-out
              lg:hidden mobile-menu z-40
              ${menuOpen ? 'translate-x-0' : 'translate-x-full'}
            `}
          >
            <div className="flex flex-col h-full">
              {/* Menu Items */}
              <div className="flex-1 overflow-y-auto py-6 px-6">
                {navItems.map((item) => (
                  <div
                    key={item.id}
                    onClick={() => handleScroll(item.id)}
                    className="py-4 border-b border-neutral-800 hover:text-red-500 cursor-pointer transition text-sm uppercase tracking-wider"
                  >
                    {item.name}
                  </div>
                ))}
              </div>

              {/* Mobile Ticket Button */}
              <div className="p-6 border-t border-neutral-800">
                <button className="w-full bg-red-600 hover:bg-red-700 px-4 py-3 text-sm font-semibold transition">
                  GET TICKETS
                </button>
              </div>
            </div>
          </div>
        </nav>

        {/* HERO */}
        <section
          id="home"
          className="relative pt-16 min-h-screen flex items-center bg-black overflow-hidden"
        >
          {/* BACKGROUND IMAGE */}
          <div className="absolute inset-0 flex justify-end items-center pointer-events-none">
            <img
              src="/fighter.png"
              alt="fighter"
              className="h-full w-auto max-w-none object-contain opacity-60 md:opacity-80"
              style={{ maxHeight: '100vh' }}
            />
          </div>

          {/* GRADIENT OVERLAY */}
          <div className="absolute inset-0 bg-gradient-to-r from-black via-black/95 md:via-black/90 to-transparent" />

          {/* CONTENT */}
          <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 w-full py-12 md:py-16">
            <div className="w-full max-w-full sm:max-w-xl lg:max-w-2xl">
              <p className="text-red-500 text-xs uppercase tracking-[2px] mb-4">
                GFC GLOBAL 1: ORIGIN
              </p>

              <h1 className="font-[Anton] italic uppercase tracking-wide leading-[0.9] text-4xl sm:text-5xl md:text-7xl lg:text-8xl xl:text-9xl">
                <span className="block">FIGHTS.</span>
                <span className="block">STORIES.</span>
                <span className="block text-red-500">LEGENDS.</span>
              </h1>

              <p className="mt-6 text-gray-300 text-sm sm:text-base max-w-md">
                India's Next Combat Sports Movement
              </p>

              <div className="flex flex-col sm:flex-row gap-3 sm:gap-4 mt-8 max-w-md">
                <button className="bg-red-600 hover:bg-red-700 px-6 py-3 text-sm font-semibold transition">
                  GET TICKETS
                </button>
                <button className="border border-white hover:bg-white hover:text-black px-6 py-3 text-sm transition flex items-center justify-center gap-2">
                  <span>▶</span> WATCH TRAILER
                </button>
              </div>
            </div>
          </div>
        </section>

        {/* FEATURES */}
        <section id="about" className="border-t border-neutral-900">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 py-12 md:py-16">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-8 lg:gap-6">
              {features.map((item, i) => (
                <div
                  key={i}
                  className="text-center pb-6 sm:pb-0 border-b sm:border-b-0 sm:border-r border-neutral-800 last:border-none sm:pr-6"
                >
                  <i className={`fa ${item.icon} text-red-500 text-3xl mb-4`} />
                  <h3 className="text-sm font-bold uppercase mb-2">
                    {item.title}
                  </h3>
                  <p className="text-xs text-gray-500">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* ABOUT + FIGHTERS */}
        <section id="fighters" className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 py-12 md:py-16">
          <div className="grid lg:grid-cols-2 gap-10 lg:gap-16 items-start">
            {/* LEFT TEXT */}
            <div className="max-w-xl">
              <p className="text-red-600 text-xs tracking-widest uppercase mb-4">
                ABOUT GFC
              </p>

              <h2 className="text-3xl md:text-4xl lg:text-5xl font-extrabold leading-tight uppercase">
                WE ARE BUILDING <br />
                MORE THAN EVENTS.
                <br />
                <span className="text-red-600">
                  WE ARE BUILDING A MOVEMENT.
                </span>
              </h2>

              <p className="text-gray-400 text-sm md:text-base mt-6 leading-relaxed">
                GFC is a combat sports platform focused on fighters, content and
                culture. Our mission is to give fighters the stage they deserve
                and fans the experience they will never forget.
              </p>

              <button className="mt-8 border border-gray-600 px-6 py-3 text-sm uppercase hover:bg-white hover:text-black transition">
                KNOW MORE →
              </button>
            </div>

            {/* FIGHTERS GRID */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {fighters.map((f, i) => (
                <div
                  key={i}
                  className="relative bg-[#0c0c0c] border border-gray-800 overflow-hidden group"
                >
                  {/* IMAGE */}
                  <img
                    src={f.img}
                    alt={f.name}
                    className="h-[300px] sm:h-[340px] w-full object-cover"
                  />

                  {/* GRADIENT OVERLAY */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black via-black/50 to-transparent" />

                  {/* CONTENT */}
                  <div className="absolute bottom-0 left-0 right-0 p-4 text-center">
                    <h3 className="font-bold text-sm tracking-wide uppercase">
                      {f.name}
                    </h3>
                    <p className="text-red-600 text-xs uppercase mt-1">
                      {f.tag1}
                    </p>
                    <p className="text-red-600 text-xs uppercase">{f.tag2}</p>
                    <button className="mt-3 border border-gray-600 px-4 py-1.5 text-[10px] uppercase hover:bg-white hover:text-black transition">
                      VIEW PROFILE
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* EVENT + COUNTDOWN */}
        <section id="origin" className="border-t border-gray-800 bg-[#0a0a0a] overflow-hidden">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 py-12 md:py-16">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 lg:gap-12 items-center">
              {/* LEFT POSTER */}
              <div className="flex justify-center lg:justify-start">
                <img
                  src="/event.png"
                  alt="event"
                  className="w-full max-w-[280px] sm:max-w-[320px] lg:max-w-full object-cover border border-gray-800"
                />
              </div>

              {/* CENTER TEXT */}
              <div className="text-center lg:text-left">
