                    return (
                      <a
                        key={i}
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="w-10 h-10 flex items-center justify-center border border-gray-700 text-gray-400 hover:text-red-500 hover:border-red-500 hover:shadow-[0_0_10px_rgba(239,68,68,0.6)] transition-all duration-300"
