              {/* SUBSCRIBE */}
              <div className="w-full">
                <h3 className="text-sm font-semibold uppercase tracking-wider mb-6">
                  Stay Updated
                </h3>

                <p className="text-gray-400 text-sm mb-5 leading-relaxed">
                  Get the latest updates, fight announcements and exclusive content.
                </p>

                {/* INPUT */}
                <div className="flex flex-col sm:flex-row border border-gray-700 focus-within:border-red-500 transition overflow-hidden">
                  <input
                    type="email"
