              </div>
            </div>

            {/* BOTTOM */}
            <div className="mt-12 pt-6 border-t border-[#1a1a1a] text-center">
              <p className="text-gray-600 text-xs tracking-wide">
                © 2025 GFC Global. All Rights Reserved.
              </p>
            </div>
          </div>
        </footer>
      </div>
    </>
